def grep(pattern, flags, files):
    import re
    import os

    # 1. Parse flags
    flags = flags.split()
    ignore_case = '-i' in flags
    invert = '-v' in flags
    line_num = '-n' in flags
    only_files = '-l' in flags
    exact = '-x' in flags

    # 2. Build regex for fixed-string search
    if ignore_case:
        pattern = pattern.lower()
    if exact:
        pattern = re.escape(pattern)
    else:
        pattern = re.escape(pattern)  # treat as literal anyway

    # 3. Helper to process one file
    def process_file(filename):
        try:
             with open(filename, 'r') as f:
                 lines = f.readlines()
         except FileNotFoundError:
             return []

