             line = line.rstrip('\n')  # strip trailing newline for matching
             if ignore_case:
                 line = line.lower()
             match = bool(pattern in line) if not exact else (line == pattern)
             if invert:
                 match = not match
             if match:
                 if only_files:
                     results.append(filename + '\n')
                     break  # first match wins for -l
 else:
                     prefix = f"{filename}:" if len(files) > 1 else ""
                     if line_num:
                         results.append(f"{prefix}{i}:{line}\n")
